export type ParsedRequestRedeemInstruction<
  TProgram extends string = typeof MUTAV_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** The investor. Pays the request's rent. */
    owner: TAccountMetas[0];
    config: TAccountMetas[1];
    state: TAccountMetas[2];
    redeemRequest: TAccountMetas[3];
    /**
     * The owner's share account. Owner, never delegate (spec §5): a delegate
     * approved by another wallet fails here.
     */
    ownerShares: TAccountMetas[4];
    pendingRedemptions: TAccountMetas[5];
    shareMint: TAccountMetas[6];
    shareTokenProgram: TAccountMetas[7];
    systemProgram: TAccountMetas[8];
    eventAuthority: TAccountMetas[9];
    program: TAccountMetas[10];
  };
  data: RequestRedeemInstructionData;
};

export function parseRequestRedeemInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRequestRedeemInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 11,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      owner: getNextAccount(),
      config: getNextAccount(),
      state: getNextAccount(),
      redeemRequest: getNextAccount(),
      ownerShares: getNextAccount(),
      pendingRedemptions: getNextAccount(),
      shareMint: getNextAccount(),
      shareTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
    },
    data: getRequestRedeemInstructionDataDecoder().decode(instruction.data),
  };
}
